(()=>{
const words={
 companyCalendar:['公司行事曆','Company calendar','Calendario de empresa','Lịch công ty'],
 calendarHelp:['各國獨立設定。週六、日於隔週一中午 12:00；平日休假於隔天中午 12:00，以當地時間執行，不需登入。僅無任何點檢資料的設備自動標記 X 停用。','Each country has its own calendar. Weekends are processed on Monday at noon; weekday holidays on the next day at noon, local time, without login. Only equipment with no inspection data is marked X.','Cada país tiene su calendario. Fines de semana: lunes a las 12:00; festivos entre semana: día siguiente a las 12:00, hora local y sin iniciar sesión. Solo se marca X si no hay datos de inspección.','Mỗi quốc gia có lịch riêng. Cuối tuần xử lý lúc 12:00 thứ Hai; ngày nghỉ trong tuần lúc 12:00 hôm sau, theo giờ địa phương, không cần đăng nhập. Chỉ đánh dấu X khi chưa có dữ liệu kiểm tra.'],
 calendarHolidayHelp:['請依公司公告新增國定假日與補班日；未登錄的平日視為工作日。補班日優先，不會自動停用。','Add public holidays and makeup workdays according to company notices. Unlisted weekdays are working days. Workday overrides prevent automatic stops.','Añada festivos y jornadas de recuperación según la empresa. Días laborables no registrados se consideran de trabajo. Las excepciones laborales impiden la parada automática.','Thêm ngày lễ và ngày làm bù theo thông báo công ty. Ngày thường chưa đăng ký là ngày làm việc. Ngày làm bù không tự đánh dấu ngừng máy.'],
 calendarEnabled:['啟用休假日自動停用','Enable automatic holiday stops','Activar parada automática en días de descanso','Bật tự động ngừng máy ngày nghỉ'],
 calendarWeekend:['週六、日休假','Saturday and Sunday off','Descanso sábado y domingo','Nghỉ thứ Bảy và Chủ nhật'],
 calendarTimezone:['當地時區','Local time zone','Zona horaria local','Múi giờ địa phương'],
 calendarStart:['開始適用日期','Effective from','Vigente desde','Ngày bắt đầu áp dụng'],
 calendarStartHelp:['不回填開始日期以前的空白資料；天車不適用。暫停功能會保留既有系統註記。','No backfill before the effective date. Cranes are excluded. Pausing retains existing system marks.','No se rellenan fechas anteriores. Se excluyen grúas. Pausar conserva las marcas existentes.','Không bổ sung trước ngày bắt đầu. Loại trừ cầu trục. Tạm dừng vẫn giữ dấu hệ thống đã có.'],
 calendarHoliday:['休假日／國定假日','Holiday / public holiday','Descanso / festivo','Ngày nghỉ / ngày lễ'],
 calendarWorkday:['補班／工作日','Makeup / working day','Jornada de recuperación / laboral','Ngày làm bù / làm việc'],
 calendarDate:['日期','Date','Fecha','Ngày'],
 calendarEnd:['結束日期（可連續新增）','End date (add a range)','Fecha final (añadir intervalo)','Ngày kết thúc (thêm khoảng ngày)'],
 calendarType:['日期類型','Day type','Tipo de día','Loại ngày'],
 calendarName:['休假／補班名稱','Holiday / workday name','Nombre del festivo / jornada','Tên ngày nghỉ / làm bù'],
 calendarAdd:['新增／更新日期','Add / update dates','Añadir / actualizar fechas','Thêm / cập nhật ngày'],
 calendarDelete:['移除','Remove','Eliminar','Xóa'],
 calendarSave:['儲存公司行事曆','Save company calendar','Guardar calendario','Lưu lịch công ty'],
 calendarSaved:['已儲存','Saved','Guardado','Đã lưu'],
 calendarRefreshNeeded:['行事曆已儲存，請重新整理以更新看板。','Calendar saved. Refresh to update the board.','Calendario guardado. Actualice el panel.','Đã lưu lịch. Tải lại để cập nhật bảng.'],
 calendarUnsaved:['有尚未儲存的變更','Unsaved changes','Cambios sin guardar','Có thay đổi chưa lưu'],
 calendarDiscard:['捨棄尚未儲存的行事曆變更？','Discard unsaved calendar changes?','¿Descartar cambios del calendario?','Bỏ thay đổi lịch chưa lưu?'],
 calendarInvalid:['請檢查日期、年份、時區及名稱；開始日期不可早於已啟用的日期。','Check dates, year, time zone and name. The effective date cannot move earlier.','Revise fechas, año, zona y nombre. No se puede adelantar la fecha de inicio.','Kiểm tra ngày, năm, múi giờ và tên. Không thể dời ngày bắt đầu sớm hơn.'],
 calendarConflict:['其他管理員已更新，請重新載入行事曆後再修改。','Another administrator updated this calendar. Reload before editing.','Otro administrador actualizó el calendario. Recárguelo antes de editar.','Quản trị viên khác đã cập nhật. Tải lại lịch trước khi sửa.'],
 calendarReload:['重新載入行事曆','Reload calendar','Recargar calendario','Tải lại lịch'],
 calendarEmpty:['本年度尚未設定休假或補班日期。','No holiday or workday overrides for this year.','No hay excepciones para este año.','Chưa có ngày nghỉ hoặc làm bù cho năm này.'],
 calendarLastRun:['最近排程執行','Last scheduled run','Última ejecución','Lần chạy gần nhất'],
 calendarPending:['等待下一次排程','Waiting for next run','Esperando próxima ejecución','Chờ lần chạy tiếp theo'],
 calendarAutoStop:['X 停用（休假日系統自動補登）','X Stopped (automatic holiday entry)','X Parado (registro automático por descanso)','X Ngừng máy (tự ghi ngày nghỉ)'],
 calendarLegend:['X：依公司行事曆自動補登的休假日停用，並非人工點檢或簽核；任何班別已有資料（含草稿）不補登，後續可補登實際結果。','X: automatic rest-day stop from the company calendar, not a human inspection or approval. Any existing shift record, including drafts, prevents it. Actual results may be entered later.','X: parada automática según el calendario, no inspección ni aprobación humana. Cualquier registro, incluso borrador, la impide. Se pueden registrar resultados reales después.','X: tự ghi ngừng máy ngày nghỉ theo lịch, không phải kiểm tra hay ký duyệt thủ công. Có dữ liệu bất kỳ ca nào, kể cả nháp, thì không tự ghi. Có thể bổ sung kết quả thực tế sau.']
};
for(const[k,v]of Object.entries(words))translations[k]=Object.fromEntries(['zh','en','es','vi'].map((l,i)=>[l,v[i]]));
let state=null,dirty=false,busy=false,epoch=0,selectedYear=new Date().getFullYear();
const oldRender=render;render=function(){if(view==='companyCalendar'&&profile?.role!=='admin')view='board';oldRender();if(profile?.role==='admin'&&activeCountry){const b=document.createElement('button');b.className='nav'+(view==='companyCalendar'?' active':'');b.dataset.view='companyCalendar';b.innerHTML=txt('companyCalendar');b.onclick=()=>{view='companyCalendar';if(!dirty)state=null;render();};$('.side').append(b);}};
const oldContent=renderContent;renderContent=function(){if(view!=='companyCalendar')return oldContent();if(profile?.role!=='admin')return;$('.page-title h1').innerHTML=txt('companyCalendar');if(state?.country!==activeCountry||state?.account!==profile.account_id)state=null;if(!state){$('#content').innerHTML=txt('loading');fetchCalendar();}else draw();};
const oldReset=resetCountry;resetCountry=function(){if(busy)return;if(dirty&&!confirm(t('calendarDiscard')))return;dirty=false;state=null;epoch++;oldReset();};
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
async function fetchCalendar(){const ticket=++epoch,country=activeCountry,account=profile.account_id;try{const r=await api({action:'calendar_get',year:selectedYear});if(ticket!==epoch||country!==activeCountry||account!==profile?.account_id)return;state={country,account,...r};dirty=false;if(view==='companyCalendar')draw();}catch(e){if(ticket===epoch&&view==='companyCalendar'){$('#content').innerHTML=`<p role="alert">${txt('error')}</p><button class="btn secondary" id="calendarRetry">${txt('calendarReload')}</button>`;$('#calendarRetry').onclick=fetchCalendar;}}}
function changed(){dirty=true;$('#calendarMessage').textContent=t('calendarUnsaved');}
function draw(){const c=state.calendar;
 $('#content').innerHTML=`<p class="notice">${txt('calendarHelp')}</p><p>${txt('calendarHolidayHelp')}</p><form id="calendarForm"><div class="editor-fields"><label><input id="calEnabled" type="checkbox" ${c.enabled?'checked':''}> ${txt('calendarEnabled')}</label><label><input id="calWeekends" type="checkbox" ${c.weekends_off?'checked':''}> ${txt('calendarWeekend')}</label><label>${txt('calendarTimezone')}<select id="calTimezone" class="select">${[...new Set([c.timezone,'Asia/Taipei','Asia/Ho_Chi_Minh','America/Mexico_City','America/Tijuana','America/Ciudad_Juarez','America/Cancun','America/Hermosillo'])].map(z=>`<option ${z===c.timezone?'selected':''}>${esc(z)}</option>`).join('')}</select></label><label>${txt('calendarStart')}<input class="select" id="calStart" type="date" value="${esc(c.effective_date)}" min="${esc(c.effective_date)}" required></label></div><p class="muted">${txt('calendarStartHelp')}</p><div class="filter-row"><label>${txt('year')} <input class="select" id="calYear" type="number" min="2000" max="2100" value="${selectedYear}" style="width:130px"></label><button type="button" id="calReload" class="btn secondary">${txt('calendarReload')}</button></div><div class="editor-fields"><label>${txt('calendarDate')}<input type="date" id="calFrom" class="select" min="${selectedYear}-01-01" max="${selectedYear}-12-31"></label><label>${txt('calendarEnd')}<input type="date" id="calTo" class="select" min="${selectedYear}-01-01" max="${selectedYear}-12-31"></label><label>${txt('calendarType')}<select class="select" id="calType"><option value="holiday">${txt('calendarHoliday')}</option><option value="workday">${txt('calendarWorkday')}</option></select></label><label>${txt('calendarName')}<input class="select" id="calName" maxlength="100"></label></div><p><button type="button" id="calAdd" class="btn secondary">${txt('calendarAdd')}</button></p><div class="table-wrap"><table class="matrix" style="min-width:500px"><thead><tr>${['calendarDate','calendarType','calendarName','actions'].map(k=>`<th>${txt(k)}</th>`).join('')}</tr></thead><tbody>${state.days.map((d,i)=>`<tr><td>${esc(d.calendar_date)}</td><td>${txt(d.day_type==='holiday'?'calendarHoliday':'calendarWorkday')}</td><td>${esc(d.label)}</td><td><button type="button" class="btn secondary" data-calendar-remove="${i}">${txt('calendarDelete')}</button></td></tr>`).join('')||`<tr><td colspan="4">${txt('calendarEmpty')}</td></tr>`}</tbody></table></div><p id="calendarMessage" role="status">${dirty?txt('calendarUnsaved'):''}</p><button class="btn primary" id="calSave" type="submit">${txt('calendarSave')}</button><p class="muted">${txt('calendarLastRun')}：${c.last_run_at?esc(new Intl.DateTimeFormat(primary==='zh'?'zh-TW':primary,{dateStyle:'medium',timeStyle:'short',timeZone:c.timezone}).format(new Date(c.last_run_at)))+' · '+esc(c.timezone):txt('calendarPending')}</p></form><p class="notice">${txt('calendarLegend')}</p>`;
 for(const[id,key,checkbox]of [['calEnabled','enabled',true],['calWeekends','weekends_off',true],['calTimezone','timezone'],['calStart','effective_date']])$('#'+id).onchange=e=>{c[key]=checkbox?e.target.checked:e.target.value;changed();};
 $('#calYear').onchange=e=>{const y=Number(e.target.value);if(!Number.isInteger(y)||y<2000||y>2100){e.target.value=selectedYear;return;}if(dirty&&!confirm(t('calendarDiscard'))){e.target.value=selectedYear;return;}selectedYear=y;fetchCalendar();};
 $('#calReload').onclick=()=>{if(!dirty||confirm(t('calendarDiscard')))fetchCalendar();};
 $$('[data-calendar-remove]').forEach(b=>b.onclick=()=>{state.days.splice(Number(b.dataset.calendarRemove),1);dirty=true;draw();});
 $('#calAdd').onclick=()=>{const from=$('#calFrom').value,to=$('#calTo').value||from,label=$('#calName').value.trim(),type=$('#calType').value;
 if(!from||!to||from>to||!from.startsWith(selectedYear+'-')||!to.startsWith(selectedYear+'-')||!label){$('#calendarMessage').textContent=t('calendarInvalid');return;}
 for(let date=new Date(from+'T00:00:00Z');date<=new Date(to+'T00:00:00Z');date.setUTCDate(date.getUTCDate()+1)){const day=date.toISOString().slice(0,10);state.days=state.days.filter(d=>d.calendar_date!==day);state.days.push({calendar_date:day,day_type:type,label});}
 state.days.sort((a,b)=>a.calendar_date.localeCompare(b.calendar_date));dirty=true;draw();};
 $('#calendarForm').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;const form=e.target;for(const el of form.elements)el.disabled=true;try{const r=await api({action:'calendar_save',year:selectedYear,revision:c.revision,timezone:c.timezone,enabled:c.enabled,weekends_off:c.weekends_off,effective_date:c.effective_date,days:state.days.map(d=>({date:d.calendar_date,type:d.day_type,label:d.label}))});state.calendar=r.calendar;dirty=false;let refreshed=true;try{const fresh=await api({action:'workspace'});data=fresh;}catch{refreshed=false;}if(view==='companyCalendar'){draw();$('#calendarMessage').textContent=t(refreshed?'calendarSaved':'calendarRefreshNeeded');}}catch(e){if(view==='companyCalendar')$('#calendarMessage').textContent=t(e.message==='record_changed'?'calendarConflict':'calendarInvalid');}finally{busy=false;for(const el of form.elements)el.disabled=false;}};
}
render();
})();
